// Package selfupdate lets shade notice and install newer releases of itself
// from GitHub. It covers the passive once-a-day notice printed after a
// command and the explicit `shade update` command. Nothing here runs
// without the user asking: the notice only reads, and the binary is only
// replaced by `shade update`.
//
// This package is hand-written, not generated by Speakeasy.
package selfupdate

import (
	"fmt"
	"strconv"
	"strings"
)

// Version is a parsed release tag: v0.3.1, 0.3.1, v1.0.0-rc.1.
type Version struct {
	Major, Minor, Patch int
	Pre                 string
}

// ParseVersion accepts an optional leading v, three dot-separated numbers
// and an optional -prerelease suffix. Build metadata (+...) is ignored.
func ParseVersion(s string) (Version, error) {
	raw := strings.TrimSpace(s)
	raw = strings.TrimPrefix(raw, "v")
	if i := strings.IndexByte(raw, '+'); i >= 0 {
		raw = raw[:i]
	}
	var v Version
	if i := strings.IndexByte(raw, '-'); i >= 0 {
		v.Pre = raw[i+1:]
		raw = raw[:i]
		if v.Pre == "" {
			return Version{}, fmt.Errorf("invalid version %q", s)
		}
	}
	parts := strings.Split(raw, ".")
	if len(parts) != 3 {
		return Version{}, fmt.Errorf("invalid version %q", s)
	}
	nums := make([]int, 3)
	for i, p := range parts {
		n, err := strconv.Atoi(p)
		if err != nil || n < 0 || (len(p) > 1 && p[0] == '0') {
			return Version{}, fmt.Errorf("invalid version %q", s)
		}
		nums[i] = n
	}
	v.Major, v.Minor, v.Patch = nums[0], nums[1], nums[2]
	return v, nil
}

// String renders the version with a leading v, the way release tags are named.
func (v Version) String() string {
	s := fmt.Sprintf("v%d.%d.%d", v.Major, v.Minor, v.Patch)
	if v.Pre != "" {
		s += "-" + v.Pre
	}
	return s
}

// Compare orders versions the semver way: numbers first, then a version
// without a prerelease suffix is newer than one with it, then prerelease
// identifiers compared piecewise (numeric before alphanumeric).
func Compare(a, b Version) int {
	switch {
	case a.Major != b.Major:
		return cmpInt(a.Major, b.Major)
	case a.Minor != b.Minor:
		return cmpInt(a.Minor, b.Minor)
	case a.Patch != b.Patch:
		return cmpInt(a.Patch, b.Patch)
	case a.Pre == b.Pre:
		return 0
	case a.Pre == "":
		return 1
	case b.Pre == "":
		return -1
	}
	as, bs := strings.Split(a.Pre, "."), strings.Split(b.Pre, ".")
	for i := 0; i < len(as) && i < len(bs); i++ {
		an, aerr := strconv.Atoi(as[i])
		bn, berr := strconv.Atoi(bs[i])
		switch {
		case aerr == nil && berr == nil:
			if an != bn {
				return cmpInt(an, bn)
			}
		case aerr == nil:
			return -1
		case berr == nil:
			return 1
		default:
			if c := strings.Compare(as[i], bs[i]); c != 0 {
				return c
			}
		}
	}
	return cmpInt(len(as), len(bs))
}

// IsNewer reports whether latest is a strictly newer version than current.
// Anything that does not parse is treated as not newer, so a bad tag or an
// odd local build never produces a notice.
func IsNewer(latest, current string) bool {
	l, err := ParseVersion(latest)
	if err != nil {
		return false
	}
	c, err := ParseVersion(current)
	if err != nil {
		return false
	}
	return Compare(l, c) > 0
}

func cmpInt(a, b int) int {
	switch {
	case a < b:
		return -1
	case a > b:
		return 1
	}
	return 0
}
